    static class Builder {
        private ChargeRequest req = new ChargeRequest();
        Builder amount(double amount) { req.amount = amount; return this; }
        Builder currency(String currency) { req.currency = currency; return this; }
        Builder idempotencyKey(String key) { req.idempotencyKey = key; return this; }
        ChargeRequest build() { return req; }
    }

