#include <bits/stdc++.h>
using namespace std;

struct ChargeRequest {
    double amount;
    string currency;
    string idempotencyKey;
};

struct PaymentResult {
    string status;
};

// backed by Redis or a DB in production, an in-memory map here for demonstration
class IdempotencyStore {
public:
    unordered_map<string, PaymentResult> store;

    optional<PaymentResult> get(const string& key) {
        auto it = store.find(key);
        if (it == store.end()) return nullopt;
        return it->second;
    }

    void put(const string& key, const PaymentResult& result) {
        store[key] = result;
    }
};

class PaymentService {
    IdempotencyStore store;
public:
    PaymentResult charge(const ChargeRequest& req) {
        const string& key = req.idempotencyKey;

        // 1. check store first
        auto cached = store.get(key);
        if (cached.has_value()) {
            cout << "Idempotent replay for key=" << key << endl;
            return cached.value();
        }

        // 2. execute, only runs once per key
        PaymentResult result = doCharge(req.amount, req.currency);

        // 3. store result (with a TTL in a real store)
        store.put(key, result);

        return result;
    }

private:
    PaymentResult doCharge(double amount, const string& currency) {
        return {"charged " + to_string(amount) + " " + currency};
    }
};

int main() {
    PaymentService service;
    ChargeRequest req{100.0, "USD", "key-abc"};

    cout << service.charge(req).status << endl;
    cout << service.charge(req).status << endl;   // same key, replayed from store
    return 0;
}

