// simulates a Redis client's SET NX (set-if-not-exists) as a distributed lock,
// using an in-memory set here since there is no real Redis in this demo
class FakeRedis {
    Set<String> locks = ConcurrentHashMap.newKeySet();

    boolean setNX(String key) {
        return locks.add(key);   // true only if key was not already present
    }

    void del(String key) {
        locks.remove(key);
    }
}

class PaymentService {
    FakeRedis redis = new FakeRedis();
    Map<String, PaymentResult> store = new ConcurrentHashMap<>();

    PaymentResult charge(ChargeRequest req) {
        String key = req.getIdempotencyKey();
        String lockKey = "lock:" + key;

        // try to acquire lock, only first caller wins
        boolean locked = redis.setNX(lockKey);

        if (!locked) {
            // another thread is executing, wait for result
            return waitForResult(key);
        }

        try {
            PaymentResult cached = store.get(key);
            if (cached != null) return cached;

            PaymentResult result = new PaymentResult("charged " + req.getAmount() + " " + req.getCurrency());
            store.put(key, result);
            return result;
        } finally {
            redis.del(lockKey);
        }
