using namespace std;

struct PaymentResult {
    string status;
};

struct ChargeRequest {
    double amount;
    string currency;
    string idempotencyKey;
};

// simulates a Redis client's SET NX (set-if-not-exists) as a distributed lock,
// using an in-memory set here since there is no real Redis in this demo
class FakeRedis {
public:
    set<string> locks;

    bool setNX(const string& key) {
        if (locks.count(key)) return false;
        locks.insert(key);
        return true;
    }

    void del(const string& key) {
        locks.erase(key);
    }
};

class PaymentService {
    FakeRedis redis;
    unordered_map<string, PaymentResult> store;
public:
    PaymentResult charge(const ChargeRequest& req) {
        const string& key = req.idempotencyKey;
        string lockKey = "lock:" + key;

        // try to acquire lock, only first caller wins
        bool locked = redis.setNX(lockKey);

        if (!locked) {
            // another thread is executing, wait for result
            return waitForResult(key);
        }

        auto cached = store.find(key);
        if (cached != store.end()) {
            redis.del(lockKey);
            return cached->second;
        }

        PaymentResult result{"charged " + to_string(req.amount) + " " + req.currency};
        store[key] = result;
        redis.del(lockKey);
        return result;
    }

    PaymentResult waitForResult(const string& key) {
        return store[key];
    }
};

