    amount = 250.0

    try:
        result = payment_repo.insert(Payment(key, account_id, amount, "COMPLETED"))
    except DuplicateKeyError:
        # duplicate key, return existing record
        result = payment_repo.find_by_idempotency_key(key)
    print(f"Status: {result.status}")

    # second attempt with the same key hits the duplicate branch
    try:
        result = payment_repo.insert(Payment(key, account_id, amount, "COMPLETED"))
    except DuplicateKeyError:
        result = payment_repo.find_by_idempotency_key(key)
