import hashlib


class ConflictError(Exception):
    pass


class Entry:
    def __init__(self, fingerprint, result):
        self.fingerprint = fingerprint
        self.result = result


class IdempotencyStore:
    def __init__(self):
        self.store = {}

    def get_or_execute(self, key, fingerprint, action):
        existing = self.store.get(key)
        if existing is not None:
            if existing.fingerprint != fingerprint:
                raise ConflictError("Key already used with different payload")
            return existing.result
        result = action()
        self.store[key] = Entry(fingerprint, result)
        return result

    @staticmethod
    def sha256(text):
        return hashlib.sha256(text.encode()).hexdigest()


if __name__ == "__main__":
    idempotency_store = IdempotencyStore()
    key = "key-1"

    # fingerprint = SHA-256 hash of sorted request body
    fingerprint = IdempotencyStore.sha256('{"amount":100}')

    result = idempotency_store.get_or_execute(key, fingerprint, lambda: "charged $100")
    print(f"Result: {result}")

    # same key and same fingerprint, replayed
    replay = idempotency_store.get_or_execute(key, fingerprint, lambda: "charged $100")
    print(f"Replay: {replay}")

    # same key but different payload, conflict
    try:
        different_fingerprint = IdempotencyStore.sha256('{"amount":500}')
        idempotency_store.get_or_execute(key, different_fingerprint, lambda: "charged $500")
    except ConflictError as e:
        print(f"Conflict detected: {e}")

