import java.util.*;
import java.security.MessageDigest;

class ConflictException extends RuntimeException {
    ConflictException(String msg) { super(msg); }
}

class Entry {
    String fingerprint;
    Object result;
    Entry(String fingerprint, Object result) {
        this.fingerprint = fingerprint;
        this.result = result;
    }
}

class IdempotencyStore {
    Map<String, Entry> store = new HashMap<>();

    Object getOrExecute(String key, String fingerprint, java.util.function.Supplier<Object> action) {
        Entry existing = store.get(key);
        if (existing != null) {
            if (!existing.fingerprint.equals(fingerprint))
                throw new ConflictException("Key already used with different payload");
            return existing.result;
        }
        Object result = action.get();
        store.put(key, new Entry(fingerprint, result));
        return result;
    }

    static String sha256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(input.getBytes());
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) hex.append(String.format("%02x", b));
            return hex.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        IdempotencyStore idempotencyStore = new IdempotencyStore();
        String key = "key-1";

        // fingerprint = SHA-256 hash of sorted request body
        String fingerprint = IdempotencyStore.sha256("{\"amount\":100}");

        Object result = idempotencyStore.getOrExecute(key, fingerprint, () -> "charged $100");
        System.out.println("Result: " + result);

        // same key and same fingerprint, replayed
        Object replay = idempotencyStore.getOrExecute(key, fingerprint, () -> "charged $100");
        System.out.println("Replay: " + replay);

        // same key but different payload, conflict
        try {
            String differentFingerprint = IdempotencyStore.sha256("{\"amount\":500}");
            idempotencyStore.getOrExecute(key, differentFingerprint, () -> "charged $500");
        } catch (ConflictException e) {
            System.out.println("Conflict detected: " + e.getMessage());
        }
    }
}

