#include <bits/stdc++.h>
using namespace std;

struct ConflictException : public runtime_error {
    ConflictException(const string& msg) : runtime_error(msg) {}
};

struct Entry {
    string fingerprint;
    string result;
};

class IdempotencyStore {
public:
    unordered_map<string, Entry> store;

    template <typename Func>
    string getOrExecute(const string& key, const string& fingerprint, Func action) {
        auto it = store.find(key);
        if (it != store.end()) {
            if (it->second.fingerprint != fingerprint)
                throw ConflictException("Key already used with different payload");
            return it->second.result;
        }
        string result = action();
        store[key] = {fingerprint, result};
        return result;
    }

    // simplified stand-in for a real SHA-256 hash, just for demo purposes
    static string fingerprintOf(const string& input) {
        return "fp-" + to_string(hash<string>{}(input));
    }
};

int main() {
    IdempotencyStore idempotencyStore;
    string key = "key-1";

    // fingerprint represents a hash of the sorted request body
    string fingerprint = IdempotencyStore::fingerprintOf(R"({"amount":100})");

    string result = idempotencyStore.getOrExecute(key, fingerprint, []() { return string("charged $100"); });
    cout << "Result: " << result << endl;

    // same key and same fingerprint, replayed
    string replay = idempotencyStore.getOrExecute(key, fingerprint, []() { return string("charged $100"); });
    cout << "Replay: " << replay << endl;

    // same key but different payload, conflict
    try {
        string differentFingerprint = IdempotencyStore::fingerprintOf(R"({"amount":500})");
        idempotencyStore.getOrExecute(key, differentFingerprint, []() { return string("charged $500"); });
    } catch (const ConflictException& e) {
        cout << "Conflict detected: " << e.what() << endl;
    }
    return 0;
}
